const recomputeStats = `-- name: RecomputeStats :exec

INSERT INTO sheet_stats (uri, rating_count, rating_avg, rating_score, favorite_count, fork_count)
SELECT $1::text, r.n, COALESCE(r.avg, 0),
    ($2::float8 * $3::float8 + COALESCE(r.total, 0))
        / ($3::float8 + r.n),
    f.n, k.n
FROM
    (SELECT COUNT(*)::int AS n, AVG(value)::float8 AS avg, SUM(value)::float8 AS total
     FROM (SELECT DISTINCT ON (did) value FROM ratings WHERE subject_uri = $1::text
           ORDER BY did, created_at DESC, uri DESC) newest) r,
    (SELECT COUNT(DISTINCT did)::int AS n FROM favorites WHERE subject_uri = $1::text) f,
    (SELECT COUNT(*)::int AS n FROM sheets WHERE fork_of_uri = $1::text) k
ON CONFLICT (uri) DO UPDATE SET
    rating_count = excluded.rating_count, rating_avg = excluded.rating_avg,
    rating_score = excluded.rating_score, favorite_count = excluded.favorite_count,
    fork_count = excluded.fork_count
`

type RecomputeStatsParams struct {
	Uri         string
	PriorMean   float64
	PriorWeight float64
}

// Ratings, favorites, stats ----------------------------------------------
// An account's newest rating of a sheet is the one that counts; the score
// is a Bayesian average toward prior_mean.
func (q *Queries) RecomputeStats(ctx context.Context, arg RecomputeStatsParams) error {
	_, err := q.db.Exec(ctx, recomputeStats, arg.Uri, arg.PriorMean, arg.PriorWeight)
	return err
}

