const searchSheets = `-- name: SearchSheets :many
WITH q AS (SELECT to_tsquery('simple', $1::text) AS query),
hits AS (
    SELECT s.uri,
        (CASE WHEN to_tsvector('simple', s.names) @@ q.query THEN 4 ELSE 0 END)
            + 2 * GREATEST(word_similarity($2::text, s.names),
                           word_similarity($3::text, s.names_compact))
            + ts_rank(s.search, q.query) AS rank,
        CASE WHEN to_tsvector('simple', s.lyrics) @@ q.query
            THEN ts_headline('simple', s.lyrics, q.query, $4::text)
            ELSE '' END AS snip
    FROM sheets s, q
    WHERE s.search @@ q.query
        OR $2::text <% s.names
        OR $3::text <% s.names_compact
    ORDER BY rank DESC
    LIMIT 500
)
SELECT ss.uri, ss.did, ss.rkey, ss.cid, ss.title, ss.artist, ss.album, ss.artist_slug, ss.title_slug, ss.kind, ss.key, ss.capo, ss.tuning, ss.difficulty, ss.tags, ss.fork_of_uri, ss.fork_of_cid, ss.created_at, ss.updated_at, ss.handle, ss.display_name, ss.avatar, ss.rating_count, ss.rating_avg, ss.rating_score, ss.favorite_count, ss.fork_count, h.snip::text AS snippet
FROM hits h JOIN sheet_summaries ss ON ss.uri = h.uri
ORDER BY h.rank DESC
`

type SearchSheetsParams struct {
	Query        string
	Plain        string
	Compact      string
	HeadlineOpts string
}

type SearchSheetsRow struct {
	SheetSummary SheetSummary
	Snippet      string
}

// Every word must match (the last as a prefix), or the names must be a
// near miss, spaced or not ("deathcab", "death cab"). A title or artist
// match always outranks a lyrics-only one: it gets a flat bonus, and
// ts_rank's lyric weight is tiny so a word repeated through a chorus
// can't pile up past it.
func (q *Queries) SearchSheets(ctx context.Context, arg SearchSheetsParams) ([]SearchSheetsRow, error) {
	rows, err := q.db.Query(ctx, searchSheets,
		arg.Query,
		arg.Plain,
		arg.Compact,
		arg.HeadlineOpts,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchSheetsRow{}
	for rows.Next() {
		var i SearchSheetsRow
		if err := rows.Scan(
			&i.SheetSummary.Uri,
			&i.SheetSummary.Did,
			&i.SheetSummary.Rkey,
			&i.SheetSummary.Cid,
			&i.SheetSummary.Title,
			&i.SheetSummary.Artist,
			&i.SheetSummary.Album,
			&i.SheetSummary.ArtistSlug,
			&i.SheetSummary.TitleSlug,
			&i.SheetSummary.Kind,
			&i.SheetSummary.Key,
			&i.SheetSummary.Capo,
			&i.SheetSummary.Tuning,
			&i.SheetSummary.Difficulty,
			&i.SheetSummary.Tags,
			&i.SheetSummary.ForkOfUri,
			&i.SheetSummary.ForkOfCid,
			&i.SheetSummary.CreatedAt,
			&i.SheetSummary.UpdatedAt,
			&i.SheetSummary.Handle,
			&i.SheetSummary.DisplayName,
			&i.SheetSummary.Avatar,
			&i.SheetSummary.RatingCount,
			&i.SheetSummary.RatingAvg,
			&i.SheetSummary.RatingScore,
			&i.SheetSummary.FavoriteCount,
			&i.SheetSummary.ForkCount,
			&i.Snippet,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

